def compute(vars):
    net_income = vars["Net Income"]
    revenue = vars["Revenue"]
    multiplier = vars["100"]

    if revenue == 0:
        return {
            "value": None,
            "trace": {
                "Net Income": net_income,
                "Revenue": revenue,
                "100": multiplier,
                "output_meta": {
                    "currency": None,
                    "scale": None,
                    "unit": "percentage",
                },
            },
        }

    value = (net_income / revenue) * multiplier
    return {
        "value": value,
        "trace": {
            "Net Income": net_income,
            "Revenue": revenue,
            "100": multiplier,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage",
            },
        },
    }
